import {createSerialPoller,paymentDisplayState,workspaceSignature} from './live.js';
const app=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=c=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(c/100);
let state={projects:[],reviews:[],proposals:[],config:{},user:null},view='overview',current=null,review=null,busy=false;
let authInfo={firstAccount:false,legacyProjects:0};
async function api(path,data){
 let response;try{response=await fetch('/api/'+path,{...(data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{}),signal:AbortSignal.timeout(path.includes('/capture')?120000:65000)});}catch(error){throw Error(error.name==='TimeoutError'?'The request took too long. Your saved work is safe. Check the current status before retrying.':'Cannot reach ScopePay. Check your connection; automatic updates will retry.');}
 let result;try{result=await response.json();}catch{throw Error('ScopePay returned an unreadable response. Please retry.');}
 if(!response.ok){const error=Object.assign(Error(result.error||'Request failed.'),{status:response.status});if(response.status===401&&!path.startsWith('auth')&&path!=='profile/password'&&location.pathname!=='/client'){state={projects:[],reviews:[],proposals:[],config:{},user:null};authScreen('login');}throw error;}
 if(data&&(/^(projects|review|proposals|profile)$/.test(path)||/^client\/.+\/(accept|order|capture|cancel)$/.test(path)))announceWorkspaceChange();return result;
}
let toastTimer;const toast=s=>{const el=document.querySelector('#toast');clearTimeout(toastTimer);el.textContent=s;el.style.display='block';toastTimer=setTimeout(()=>el.style.display='none',5000)};
const date=s=>new Date(s).toLocaleDateString('en-US',{month:'short',day:'numeric'});
const btn=(label,action,primary=false)=>`<button class="btn ${primary?'primary':''}" data-action="${action}">${label}</button>`;
function shell(content){
 workspacePaintPending=false;landingCleanup();
 const page=navItems.find(n=>n[0]===view)?.[2]||({create:'New project',project:current?.name||'Project',request:'Review request',review:'Review findings',proposal:'Proposal details'}[view])||'Workspace';
 const pending=realProposals().filter(p=>p.status!=='paid').length;
 app.innerHTML=`<a class="skip-link" href="#main-content">Skip to content</a><div class="shell"><aside class="sidebar" aria-label="Workspace navigation"><a class="brand" href="/" aria-label="ScopePay home"><span class="mark">s<span></span></span>ScopePay<span class="brand-period">.</span></a><div class="workspace-label"><span class="workspace-square">${esc(initials(state.user?.name)||'MY')}</span><div><strong>My workspace</strong><small>Personal account</small></div><span class="workspace-dot"></span></div><div class="nav-label">WORKSPACE</div><nav aria-label="Primary">${navItems.map(([id,symbol,label],i)=>`${i===4?'<div class="nav-label manage-label">MANAGE</div>':''}<button class="nav ${view===id||id==='projects'&&['project','create','request'].includes(view)||id==='reviews'&&view==='review'||id==='history'&&view==='proposal'?'active':''}" data-nav="${id}" ${view===id?'aria-current="page"':''}>${icon(symbol,19)}<span>${label}</span>${id==='history'&&pending?`<span class="nav-count">${pending}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="sidebar-help" data-help>${icon('help',18)}<span>Workspace guide</span>${icon('external',13)}</button><div class="sidebar-security"><span class="status-dot"></span>Sandbox environment<span class="hint">${state.config.paypal?'Credentials configured':'Setup needed'}</span></div><button class="profile" data-nav="profile"><span class="avatar">${esc(initials(state.user?.name))}</span><span class="profile-copy"><strong>${esc(state.user?.name||'Your account')}</strong><small>${esc(state.user?.email||'')}</small></span>${icon('chevron',15)}</button></div></aside><div class="main-area"><header class="topbar"><div class="breadcrumbs"><span>Workspace</span>${icon('chevron',12)}<strong>${esc(page)}</strong></div><div class="topbar-actions"><button class="search-launch" id="search-launch" aria-label="Search workspace">${icon('search',17)}<span>Search anything…</span><kbd>Ctrl K</kbd></button><button class="icon-btn" data-help aria-label="Open workspace guide">${icon('help',19)}</button><button class="icon-btn attention-button" id="attention-launch" aria-label="View items needing attention">${icon('bell',19)}${pending?'<span class="notification-dot"></span>':''}</button><span id="workspace-live" class="sync-indicator" role="status">Auto updates</span><span class="topbar-divider"></span>${themeButton()}<span class="sandbox"><span class="status-dot"></span>Sandbox mode</span><details class="user-menu"><summary class="avatar top-avatar" aria-label="Open account menu">${esc(initials(state.user?.name))}</summary><div class="user-menu-panel"><div><strong>${esc(state.user?.name)}</strong><small>${esc(state.user?.email)}</small></div><button data-nav="profile">${icon('user',16)}Account settings</button><button data-product-home>${icon('external',16)}Product home</button><button data-logout>${icon('logout',16)}Sign out</button></div></details></div></header><main id="main-content" class="content" tabindex="-1">${content}<footer class="footer-note"><span>© ${new Date().getFullYear()} ScopePay. Clear scope. Fair pay.</span><span><span class="status-dot"></span>Account workspace <span class="footer-divider">/</span><button class="text-button" data-help>Help & information</button></span></footer></main></div></div>`;
 bind();document.title=`${page} · ScopePay`;window.scrollTo(0,0);
 document.querySelector('[data-product-home]').onclick=()=>{location.hash='home';};document.querySelector('#search-launch').onclick=searchDialog;document.querySelector('#attention-launch').onclick=attentionDialog;
}
function heading(kicker,title,sub,action=''){return `<div class="heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${action}</div></div>`;}
function projectRows(){return state.projects.length?state.projects.map(p=>`<div class="project"><div class="project-icon">${esc(p.name.slice(0,2).toUpperCase())}</div><div class="project-info"><h3>${esc(p.name)} ${p.demo?badge('','Sample'):''}</h3><p>${esc(p.client)} <span style="padding:0 7px">·</span> ${date(p.created)}</p></div><button class="btn" data-project="${p.id}">Review request <span>↗</span></button></div>`).join(''):`<div class="empty"><div class="empty-icon">▤</div><h3>A clear start for every project.</h3><p>Add your agreed scope, then review new requests against it.</p>${btn('Create your first project','create',true)}</div>`}
function overview(){
 const proposals=realProposals(),projects=state.projects.filter(p=>!p.demo),reviews=state.reviews.filter(r=>!r.demo),paid=proposals.filter(p=>p.status==='paid'),pending=proposals.filter(p=>p.status!=='paid');
 const paidTotal=paid.reduce((s,p)=>s+p.cents,0),pendingTotal=pending.reduce((s,p)=>s+p.cents,0),hours=proposals.reduce((s,p)=>s+p.items.reduce((sum,i)=>sum+(i.pricing?.estimatedHours||0),0),0);
 const greeting=new Date().getHours()<12?'Good morning':new Date().getHours()<18?'Good afternoon':'Good evening';
 const activity=[...projects.map(p=>({symbol:'folder',title:'Project created',detail:p.name,date:p.created,kind:'project',id:p.id})),...reviews.map(r=>({symbol:'review',title:'Scope review saved',detail:state.projects.find(p=>p.id===r.projectId)?.name||'Project',date:r.created,kind:'review',id:r.id})),...proposals.map(p=>({symbol:p.status==='paid'?'check':'receipt',title:p.status==='paid'?'Payment confirmed':'Proposal created',detail:p.projectName+' · '+money(p.cents),date:p.paidAt||p.created,kind:'proposal',id:p.id}))].sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,4);
 const steps=[[!!projects.length,'Create your first project','Start with the original agreement.','projects'],[!!reviews.length,'Review a client request','Understand what is actually extra.','reviews'],[!!paid.length,'Complete a sandbox payment','See the complete approval-to-payment flow.','history']];const done=steps.filter(s=>s[0]).length;
 shell(heading(`${greeting.toUpperCase()}, ${esc((state.user?.name||'there').split(' ')[0]).toUpperCase()}`,'Your work, in clear view.','A little clarity for every project. A fair price for every extra.',`<span class="today-label">${icon('clock',15)}${new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</span>${btn(icon('plus',16)+'New project','create',true)}`)+`
 <section class="stats" aria-label="Workspace summary">${[['wallet','blue','Extra work paid',money(paidTotal),paid.length+' completed sandbox payment'+(paid.length===1?'':'s')],['clock','amber','Awaiting payment',money(pendingTotal),pending.length+' open proposal'+(pending.length===1?'':'s')],['folder','violet','Active projects',String(projects.length).padStart(2,'0'),'Agreements in your workspace'],['review','teal','Hours quoted',Number(hours.toFixed(2))+' h','Estimated effort across proposals']].map(([symbol,color,label,value,sub])=>`<div class="stat"><div class="stat-top"><span>${label}</span><span class="stat-icon ${color}">${icon(symbol,19)}</span></div><strong>${value}</strong><p>${sub}</p></div>`).join('')}</section>
 <div class="overview-grid"><section class="panel chart-panel"><div class="panel-head"><div><h2>From agreed to paid</h2><p>Proposal value and completed payments</p></div><span class="date-chip">Last 6 months</span></div><div class="chart-legend"><span><i class="legend-dot quoted"></i>Quoted</span><span><i class="legend-dot paid"></i>Paid</span></div>${billingChart()}</section><section class="panel quickstart-panel"><div class="panel-head"><h2>Your next steps</h2><span class="small muted">${done} of 3</span></div><div class="panel-body"><div class="progress-track" role="progressbar" aria-label="Workspace setup" aria-valuenow="${done}" aria-valuemin="0" aria-valuemax="3"><span style="width:${done/3*100}%"></span></div><div class="quick-steps">${steps.map(([complete,title,description,target],i)=>`<button class="quick-step ${complete?'complete':''}" data-nav="${target}"><span class="quick-number">${complete?icon('check',14):i+1}</span><span><strong>${title}</strong><small>${description}</small></span>${icon('chevron',14)}</button>`).join('')}</div><button class="sample-link" data-action="sample">${icon('spark',16)} Explore the sample walkthrough ${icon('arrow',15)}</button></div></section></div>
 <div class="overview-grid lower-grid"><section class="panel"><div class="panel-head"><div><h2>Recent projects</h2><p>Your latest agreements and additions</p></div><button class="text-button" data-nav="projects">View all ${icon('arrow',14)}</button></div>${projects.length?projects.slice().reverse().slice(0,4).map(p=>projectRow(p)).join(''):emptyState('folder','Your next project starts here.','Save your original scope to bring clarity to every new request.',btn('Create a project '+icon('arrow',15),'create',true))}</section><section class="panel"><div class="panel-head"><h2>Latest activity</h2><span class="soft-label">Workspace</span></div><div class="activity-list">${activity.length?activity.map(a=>`<button class="activity-row" data-open-${a.kind}="${a.id}"><span class="activity-symbol ${a.symbol==='check'?'success':''}">${icon(a.symbol,16)}</span><span><strong>${a.title}</strong><small>${esc(a.detail)}</small></span><time>${relative(a.date)}</time></button>`).join(''):emptyState('clock','A fresh start','Project activity will be recorded here as you work.')}</div></section></div>
 <div class="workspace-banner"><span class="soft-icon">${icon('shield',22)}</span><div><strong>Your judgment. AI assistance.</strong><p>Review the evidence and estimates before sending a proposal. Sandbox payments use test funds.</p></div><button class="text-button" data-help>How ScopePay works ${icon('arrow',14)}</button></div>`);
}
function create(){shell(flowSteps('scope')+heading('01 / SET THE FOUNDATION','Start with an agreement.','Your original scope is the source of truth for every review.')+`<form id="project-form" class="panel"><div class="panel-body"><div class="two"><div class="field"><label for="name">Project name</label><input id="name" name="name" required maxlength="100" placeholder="e.g. Olive Studio website"></div><div class="field"><label for="client">Client name</label><input id="client" name="client" required maxlength="100" placeholder="e.g. Alex Morgan"></div></div><div class="field"><label for="scope">Original agreement</label><textarea id="scope" name="scope" required maxlength="12000" rows="8" placeholder="Describe included deliverables, revision allowance, and explicit exclusions. Paste the agreed wording rather than a summary."></textarea><p class="hint">The AI cites this text. Missing or ambiguous terms are flagged for clarification.</p></div><div class="field" style="max-width:320px"><label for="hourlyRate">Your hourly rate · USD (optional)</label><input id="hourlyRate" name="hourlyRate" inputmode="decimal" value="${state.user?.hourlyRate?(state.user.hourlyRate/100).toFixed(2):''}" placeholder="e.g. 20.00"><p class="hint">Defaults to your account rate. A project override is saved with each new review.</p></div><div id="form-error"></div><div class="form-footer"><p>Stored on this computer. USD payments only.</p><button class="btn primary" type="submit">Save project & continue <span>→</span></button></div></div></form>`);document.querySelector('#project-form').onsubmit=async e=>{e.preventDefault();await submit(e.target,async()=>{current=await api('projects',Object.fromEntries(new FormData(e.target)));await refresh();view='request';requestPage()})}}
function requestPage(){shell(`<button class="back" data-nav="projects">${icon('arrow',14)} All projects</button>`+flowSteps('request')+heading('02 / UNDERSTAND THE CHANGE',esc(current.name),'Paste the new request. Let the agreement do the explaining.')+`<div class="grid"><form id="request-form" class="panel"><div class="panel-head"><h2>What did ${esc(current.client)} ask for?</h2></div><div class="panel-body"><div class="field"><label for="request">Client message</label><textarea id="request" name="request" rows="8" required maxlength="12000" placeholder="Paste your client’s message here…"></textarea><p class="hint">Only paste text you have permission to share with the AI provider.</p></div><div class="field"><label for="hourlyRate">Your hourly rate · USD (optional)</label><input id="hourlyRate" name="hourlyRate" inputmode="decimal" value="${current.hourlyRate?(current.hourlyRate/100).toFixed(2):''}" placeholder="e.g. 20.00"><p class="hint">Saved to this project. Used to automatically calculate the quote from AI-estimated task hours.</p></div>${!state.config.ai?'<div class="review-banner">AI is not connected yet. Add your Gemini key in .env, or use the sample walkthrough to explore the experience.</div>':''}<div id="form-error"></div><div class="form-footer"><p>You review every finding before quoting.</p><button type="submit" class="btn primary">Analyze request <span>↗</span></button></div></div></form><aside class="panel"><div class="panel-head"><h2>Original agreement</h2>${badge('','Source')}</div><div class="panel-body"><p class="source">${esc(current.scope)}</p><div class="aside-sub"><div class="eyebrow">CLIENT</div><p class="small" style="margin-top:8px">${esc(current.client)}</p></div></div></aside></div>`);document.querySelector('#request-form').onsubmit=async e=>{e.preventDefault();await submit(e.target,async()=>{const targetId=current.id,rate=e.target.hourlyRate.value;const result=await api('review',{projectId:targetId,request:e.target.request.value,hourlyRate:rate});await refresh();if(view==='request'&&current?.id===targetId){review=result;current=state.projects.find(p=>p.id===targetId);view='review';reviewPage();}else toast('Scope review saved. Open it from Scope reviews.');})}}
function reviewPage(){shell(flowSteps('review')+heading('03 / REVIEW & QUOTE','Review the scope change.','Review the work, estimated hours, and automatically calculated proposal total.')+`${review.demo?'<div class="review-banner"><strong>Sample walkthrough</strong> · These are prewritten example findings, not live AI output. Sample proposals cannot take payments.</div>':'<div class="review-banner">AI-assisted review · Check the evidence and revision allowance. You remain responsible for the final proposal.</div>'}<form id="quote-form"><div class="grid"><section class="panel"><div class="panel-head"><h2>Request breakdown</h2><span class="small muted">${review.findings.length} findings</span></div>${review.findings.map((f,i)=>`<article class="finding"><div class="finding-top"><h3>${esc(f.title)}</h3>${badge(f.status)}</div><p>${esc(f.reason)}</p><div class="evidence"><div class="eyebrow" style="margin-bottom:5px">AGREEMENT EVIDENCE</div>${f.evidence?'“'+esc(f.evidence)+'”':'No exact supporting passage. Clarify with your client.'}</div>${f.pricing?`<div class="evidence"><strong>Calculated quote: ${money(f.pricing.suggestedCents)}</strong><p>${f.pricing.estimatedHours} estimated hours × ${money(f.pricing.hourlyRate)}/hour = ${money(f.pricing.suggestedCents)}. Effort uncertainty: ${f.pricing.hoursMin}–${f.pricing.hoursMax} hours.</p>${(f.pricing.tasks||[]).map(t=>`<div class="summary-row"><div><strong>${esc(t.name)}</strong><p>${esc(t.basis)}</p></div><span>${t.hours} h</span></div>`).join('')}<p>Assumptions: ${f.pricing.assumptions.map(esc).join('; ')}</p></div>`:''}${f.merged?'<p class="hint">Overlapping request findings combined to avoid duplicate billing.</p>':''}${f.status==='extra'&&(f.pricing||review.demo)?`<div class="two"><label class="check"><input type="checkbox" name="selected" value="${i}" checked>Include in proposal</label><div>${f.pricing?`<strong>${money(f.pricing.suggestedCents)}</strong><p class="hint">Calculated from the task hours and your saved hourly rate.</p>`:`<label for="amount-${i}">Sample price · USD</label><input id="amount-${i}" name="amount-${i}" value="60.00">`}</div></div>`:f.status==='extra'?'<p class="hint">No calculated quote available. Set your hourly rate and analyze again; if an effort estimate is still unavailable, clarify the request.</p>':''}</article>`).join('')}<div class="panel-body"><div id="quote-total" class="review-banner"></div><div class="field"><label for="message">Message to your client</label><textarea id="message" name="message" required maxlength="4000" rows="4">Thanks for the new request. I’ve separated the additional work from our original agreement below. Please review the proposed addition and its price. Any unclear integration requirements will need a separate conversation before I quote them.</textarea><p class="hint">Editable template · Only the extra work you select is included.</p></div><label class="accept"><input type="checkbox" name="pricingApproved" required>I reviewed the deliverables for overlap and approve the final prices.</label><div id="form-error"></div><button class="btn primary" type="submit">Create client proposal <span>→</span></button></div></section><aside class="panel"><div class="panel-head"><h2>The context</h2></div><div class="panel-body"><div class="eyebrow">CLIENT REQUEST</div><p class="source" style="margin-top:12px">${esc(review.request)}</p><div class="aside-sub"><div class="eyebrow">ORIGINAL AGREEMENT</div><p class="source" style="margin-top:12px">${esc(current.scope)}</p></div><div class="aside-sub"><p class="small muted">Included work stays in your original agreement. Unclear requests stay out of this proposal.</p></div></div></aside></div></form>`);const updateTotal=()=>{const selected=[...document.querySelectorAll('[name=selected]:checked')];const cents=selected.reduce((sum,el)=>sum+(review.findings[Number(el.value)].pricing?.suggestedCents||Math.round(Number(document.querySelector('[name=amount-'+el.value+']')?.value||0)*100)),0);const hours=selected.reduce((sum,el)=>sum+(review.findings[Number(el.value)].pricing?.estimatedHours||0),0);document.querySelector('#quote-total').textContent='Proposed total: '+money(cents)+(review.demo?' · sample only':' · '+Math.round(hours*100)/100+' estimated hours · subject to client approval');};document.querySelector('#quote-form').addEventListener('input',updateTotal);updateTotal();document.querySelector('#quote-form').onsubmit=async e=>{e.preventDefault();await submit(e.target,async()=>{const form=e.target,targetReviewId=review.id;const items=[...form.querySelectorAll('[name=selected]:checked')].map(el=>({index:Number(el.value),amount:form.elements['amount-'+el.value]?.value}));const p=await api('proposals',{reviewId:targetReviewId,items,message:form.message.value,pricingApproved:form.pricingApproved.checked});await refresh();if(view==='review'&&review?.id===targetReviewId){view='proposal';proposalReady(p);}else toast('Proposal saved. Open it from Proposals.');})}}
function pricingDetails(pricing){if(!pricing)return '';return `<details class="pricing-details"><summary>How this amount was calculated ${icon('down',13)}</summary><div>${(pricing.tasks||[]).map(t=>`<div class="pricing-task"><div><strong>${esc(t.name)}</strong><p>${esc(t.basis)}</p></div><span>${t.hours} h</span></div>`).join('')}<div class="pricing-formula"><span>${pricing.estimatedHours} estimated hours × ${money(pricing.hourlyRate)}/hour</span><strong>${money(pricing.suggestedCents)}</strong></div>${pricing.assumptions?.length?`<div class="pricing-assumptions"><strong>Estimate assumptions</strong><ul>${pricing.assumptions.map(a=>`<li>${esc(a)}</li>`).join('')}</ul></div>`:''}</div></details>`;}
function proposalReady(p){
 activeProposalId=p.id;
 const url=location.origin+'/client?token='+p.token,paid=p.status==='paid';
 shell(`<button class="back" data-nav="history">${icon('arrow',14)} All proposals</button>`+heading('PROPOSAL · '+esc(p.id.slice(0,8).toUpperCase()),paid?'The extra is accounted for.':'Ready for your client.',`Prepared for ${esc(p.client)} · ${fullDate(p.created)}`,`<a class="btn primary" target="_blank" rel="noopener" href="${esc(url)}">Open client view ${icon('external',15)}</a>`)+`<div class="grid"><section class="panel proposal-document"><div class="panel-head"><div><h2>${esc(p.projectName)}</h2><p>Additional work proposal</p></div>${badge(p.demo?'':statusKey(p),p.demo?'Sample proposal':statusLabel(p))}</div><div class="panel-body">${paid?`<div class="payment-success">${icon('check',20)}<div><strong>Payment confirmed</strong><p>This sandbox payment is recorded against the scope addition.</p></div></div>`:''}<div class="proposal-section-label">SCOPE ADDITION</div>${p.items.map(i=>`<article class="proposal-line"><div class="proposal-line-top"><h3>${esc(i.title)}</h3><strong>${money(i.cents)}</strong></div>${i.pricing?`<p class="hint">${i.pricing.estimatedHours} estimated hours · ${money(i.pricing.hourlyRate)}/hour</p>${pricingDetails(i.pricing)}`:''}</article>`).join('')}<div class="proposal-grand-total"><span>Total <small>USD</small></span><strong>${money(p.cents)}</strong></div><div class="proposal-section-label">MESSAGE TO CLIENT</div><p class="source">${esc(p.message)}</p><div class="proposal-scope-note">${icon('shield',16)}<p>Only the additional work listed here is included. The original project agreement remains the context for all other work.</p></div></div></section><aside><section class="panel share-panel"><div class="panel-body"><span class="feature-icon blue">${icon('external',21)}</span><h2>Share the next step.</h2><p>${p.demo?'Preview how a client sees the scope addition. This sample cannot accept payments.':paid?'The client view now includes the confirmed payment and the agreed scope addition.':'Your client can review the scope addition, accept the amount, and use PayPal sandbox checkout.'}</p><label for="client-proposal-link">Client proposal link</label><div class="share-link"><input id="client-proposal-link" readonly value="${esc(url)}"><button class="icon-btn" id="copy" aria-label="Copy client proposal link">${icon('copy',16)}</button></div><p class="hint">This local link works on this computer. It grants access to this proposal.</p><a class="btn" target="_blank" rel="noopener" href="${esc(url)}">Preview client proposal ${icon('arrow',15)}</a></div></section><section class="panel proposal-meta"><div class="panel-head"><h2>Proposal details</h2></div><div class="panel-body"><div class="summary-row"><span>Created</span><strong>${fullDate(p.created)}</strong></div><div class="summary-row"><span>Environment</span><strong>PayPal sandbox</strong></div><div class="summary-row"><span>Client acceptance</span><strong>${p.accepted?'Accepted':'Pending'}</strong></div>${p.paidAt?`<div class="summary-row"><span>Payment date</span><strong>${fullDate(p.paidAt)}</strong></div>`:''}${p.capture?`<div class="capture-box"><span>PAYPAL CAPTURE ID</span><code>${esc(p.capture)}</code></div>`:''}${p.demo?'<p class="hint">Prewritten sample · payments are disabled.</p>':''}</div></section></aside></div>`);document.querySelector('#copy').onclick=()=>copyText(url);
}

function history(){
 shell(heading('PROPOSALS & PAYMENTS','Every addition, accounted for.','Follow each proposal from client approval to confirmed payment.',`<button class="btn" id="export-proposals">${icon('download',16)}Export CSV</button>${btn(icon('refresh',16)+'Refresh status','refresh')}`)+`<div class="proposal-summary"><span>${icon('receipt',18)}<strong>${realProposals().length}</strong> proposals</span><span><i class="legend-dot paid"></i><strong>${money(realProposals().filter(p=>p.status==='paid').reduce((s,p)=>s+p.cents,0))}</strong> paid</span><span><i class="legend-dot amber"></i><strong>${money(realProposals().filter(p=>p.status!=='paid').reduce((s,p)=>s+p.cents,0))}</strong> open</span></div><section class="panel"><div class="list-toolbar"><div class="filter-tabs" aria-label="Filter proposals">${[['all','All'],['awaiting','Awaiting approval'],['accepted','Accepted'],['paid','Paid'],['sample','Samples']].map(([id,label])=>`<button data-status-filter="${id}" class="filter-tab ${listingFilter===id?'active':''}">${label}</button>`).join('')}</div><div class="input-icon compact-search">${icon('search',16)}<input id="proposal-search" aria-label="Search proposals" placeholder="Search proposals…" value="${esc(listingQuery)}"></div></div><div id="proposal-results"></div></section>`);
 const draw=()=>{const rows=filteredProposals();document.querySelector('#proposal-results').innerHTML=rows.length?`<div class="table-wrap" role="region" aria-label="Proposal records" tabindex="0"><table class="data-table"><thead><tr><th>Project / client</th><th>Amount</th><th>Status</th><th>Created</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${rows.map(p=>`<tr><td><div class="table-project"><span class="project-icon">${esc(initials(p.projectName))}</span><span><strong>${esc(p.projectName)}</strong><small>${esc(p.client)}${p.demo?' · Sample':''}</small>${p.capture?`<small class="capture-reference">Capture: ${esc(p.capture)}</small>`:''}${p.lastCheckout==='cancelled'&&p.status!=='paid'?'<small>Checkout cancelled</small>':''}</span></div></td><td class="amount-cell">${money(p.cents)}<small>USD</small></td><td>${badge(statusKey(p),statusLabel(p))}</td><td class="date-cell">${fullDate(p.created)}</td><td><button class="row-arrow" data-open-proposal="${p.id}" aria-label="Open proposal for ${esc(p.projectName)}">${icon('arrow',17)}</button></td></tr>`).join('')}</tbody></table></div>`:emptyState('receipt','No proposals in this view','Change your filter, or review a client request to create a proposal.');bindActions(document.querySelector('#proposal-results'));};
 document.querySelectorAll('[data-status-filter]').forEach(b=>b.onclick=()=>{listingFilter=b.dataset.statusFilter;document.querySelectorAll('[data-status-filter]').forEach(el=>el.classList.toggle('active',el===b));draw()});document.querySelector('#proposal-search').oninput=e=>{listingQuery=e.target.value.toLowerCase();draw()};document.querySelector('#export-proposals').onclick=exportProposals;draw();
}
function connectionRow(provider,title,description,configured){const c=state.config.connections?.[provider]||{};const label=!configured?'Not configured':c.lastError?'Check failed':c.verifiedAt?'Verified':'Ready to verify';return `<article class="connection-card"><div class="connection-card-head"><span class="service-icon ${provider==='ai'?'violet':'blue'}">${icon(provider==='ai'?'spark':'wallet',24)}</span>${badge(c.verifiedAt&&!c.lastError?'included':'',label)}</div><h2>${title}</h2><p>${description}</p><div class="connection-meta">${icon('clock',14)}${c.verifiedAt?'Verified '+new Date(c.verifiedAt).toLocaleString():'No successful check recorded'}</div>${c.lastError?`<div class="error">${esc(c.lastError)}</div>`:''}<button class="btn" data-check="${provider}" ${configured&&state.user?.role==='owner'?'':'disabled'}>${icon('refresh',15)} Verify connection</button></article>`;}
function settings(){shell(heading('CONNECTED SERVICES','The right tools, working together.','Check the services behind scope analysis, quotes, and sandbox payments.')+`<div class="connections-grid">${connectionRow('ai','Gemini AI','Reviews the agreement and request, estimates effort, and explains its assumptions.',state.config.ai)}${connectionRow('paypal','PayPal sandbox','Handles test checkout, order creation, and completed payment verification.',state.config.paypal)}<article class="connection-card"><div class="connection-card-head"><span class="service-icon teal">${icon('database',24)}</span>${badge('included','Connected')}</div><h2>Workspace database</h2><p>Account-owned projects, reviews, proposals, and payment records, stored locally.</p><div class="connection-meta">${icon('shield',14)}Persistent storage · SQLite</div><button class="btn" data-nav="profile">View account data ${icon('arrow',15)}</button></article></div><div class="settings-grid connection-notes"><section class="panel"><div class="panel-head"><h2>What a successful check means</h2></div><div class="panel-body"><div class="help-line"><span class="soft-icon">${icon('spark',18)}</span><p><strong>Gemini</strong> returned a valid analysis for a small synthetic request. Verifying may use provider quota.</p></div><div class="help-line"><span class="soft-icon">${icon('wallet',18)}</span><p><strong>PayPal</strong> accepted the current sandbox credentials. Connection checks do not create or capture payments.</p></div><div class="help-line"><span class="soft-icon">${icon('lock',18)}</span><p>Results are saved for the current configuration. Changing credentials or the model requires a new check.</p></div></div></section><aside class="panel"><div class="panel-head"><h2>Installation settings</h2></div><div class="panel-body"><p class="small muted">Service keys stay on the server. Only the installation owner can verify shared connections.</p><details class="config-details"><summary>Configuration guide ${icon('down',14)}</summary><p>Update the project’s local <code>.env</code> file with Gemini and PayPal sandbox credentials, then restart the server. Never publish that file.</p></details><div class="notice">${icon('help',17)}<p>This is a sandbox prototype. Public hosting and payment webhooks are separate deployment steps.</p></div></div></aside></div>`);document.querySelectorAll('[data-check]').forEach(button=>button.onclick=async()=>{button.disabled=true;button.innerHTML='<span class="spinner"></span>Verifying…';try{await api('connections/check',{provider:button.dataset.check});await refresh();if(view==='settings')settings();toast('Connection verified successfully.');}catch(error){await refresh();if(view==='settings')settings();toast(error.message)}});}
async function submit(form,fn){
 if(busy)return;busy=true;const button=form.querySelector('[type=submit]'),label=button.innerHTML;const stopFeedback=form.id==='request-form'?analysisFeedback(form):()=>{};
 const error=form.querySelector('#form-error,.form-error');if(error){error.textContent='';error.className='form-error';}
 form.setAttribute('aria-busy','true');button.disabled=true;button.innerHTML='<span class="spinner"></span>'+(form.id==='request-form'?'Analyzing scope…':'Working…');
 try{await fn()}catch(e){const el=form.querySelector('#form-error,.form-error');if(el&&form.isConnected){el.className='form-error';el.textContent=e.message;el.setAttribute('role','alert');el.scrollIntoView({block:'nearest'});}else toast(e.message)}finally{stopFeedback();busy=false;if(button.isConnected){button.disabled=false;button.innerHTML=label;form.setAttribute('aria-busy','false')}}
}
async function refresh(){state=await api('state')}
function render(){const result=({overview,projects:projectsPage,project:projectPage,history,reviews:savedReviews,profile:profilePage,settings,create,request:requestPage,review:reviewPage}[view]||overview)();if(result?.catch)result.catch(e=>toast(e.message));}
function bind(){bindActions();}
let clientCleanup=()=>{};
async function clientPage(){
 clientCleanup();const token=new URLSearchParams(location.search).get('token');if(!/^[a-f0-9]{48}$/.test(token||''))throw Error('This proposal link is not valid.');
 let {proposal:p,config}=await api('client/'+token),disposed=false,processing=false,lastOrderId=null,checkRunning=false,notice='',confirmationFailed=false,buttons=null,watcher=null,lastProviderCheck=0;
 document.title=p.projectName+' · Client proposal · ScopePay';
 app.innerHTML=`<div class="client-shell"><header class="client-header"><a class="brand" href="/"><span class="mark">s</span>ScopePay</a>${themeButton()}<span class="sandbox">SANDBOX PROPOSAL</span></header><section class="panel"><div class="client-hero"><div class="eyebrow">A CLEAR NEXT STEP</div><h1>${esc(p.projectName)}</h1><p class="small muted">Prepared for ${esc(p.client)} · ${fullDate(p.created)}</p></div><div class="client-body"><div id="payment-confirmation" aria-live="polite" aria-atomic="true"></div><p class="source">${esc(p.message)}</p><div class="eyebrow">ADDITIONAL WORK</div>${p.items.map(i=>`<div class="summary-row"><span>${esc(i.title)}${i.pricing?`<p class="hint">${i.pricing.estimatedHours} estimated hours × ${money(i.pricing.hourlyRate)}/hour</p>${pricingDetails(i.pricing)}`:''}</span><strong>${money(i.cents)}</strong></div>`).join('')}<div class="summary-row" style="align-items:center"><span>Total · USD</span><strong class="total">${money(p.cents)}</strong></div><p class="hint" style="margin-top:14px">Only the work listed above is added. The original agreement remains the context for all other work.</p><section id="checkout-section"><label class="accept"><input type="checkbox" id="accept" ${p.accepted?'checked':''}>I accept the additional work and total shown above.</label><div id="client-error" role="alert"></div><div id="payment"></div><button id="retry-confirm" class="btn primary" hidden>Retry payment confirmation</button><div class="payment-auto"><span>${icon('refresh',14)} Status updates automatically</span><button id="check-payment" class="text-button" type="button">Check now</button></div><p class="hint">PayPal sandbox uses test accounts and simulated funds. This is not a live payment.</p></section></div></section><p class="small muted" style="text-align:center;margin-top:24px">ScopePay · Independent prototype · PayPal sandbox payments</p></div>`;
 const payment=document.querySelector('#payment'),accept=document.querySelector('#accept'),status=document.querySelector('#payment-confirmation'),section=document.querySelector('#checkout-section'),checkButton=document.querySelector('#check-payment'),retry=document.querySelector('#retry-confirm'),errors=document.querySelector('#client-error');
 let displayKey='';
 const draw=()=>{if(disposed)return;const phase=p.demo?'sample':processing?'confirming':paymentDisplayState(p),key=JSON.stringify([phase,p.capture,p.paidAt,notice]);if(key!==displayKey){displayKey=key;const copy={sample:['Sample walkthrough','This is a prewritten example. Payments are disabled.'],ready:['Ready when you are','Review the scope and amount, then agree and pay securely with PayPal sandbox.'],awaiting:['Awaiting your PayPal payment','Checkout is open. This proposal stays unpaid until a completed capture is verified.'],approved:['Approval received · not yet paid','PayPal approval has been received. We are checking for a completed payment; you can continue checkout if confirmation did not finish.'],confirming:['Confirming your payment…','Your PayPal approval was received. Please keep this page open while the server verifies the capture.'],pending:['Payment is processing','PayPal has not confirmed completion yet. This page will update automatically. Please do not start another payment.'],cancelled:['Checkout cancelled · unpaid','No completed payment is recorded. You can continue the same checkout when ready.'],unavailable:['This checkout is no longer available','Ask the freelancer for a new proposal. No completed payment is recorded here.'],failed:['Payment not completed','PayPal did not complete the capture. Check your sandbox payment method before trying again.'],paid:['Payment confirmed','Your scope addition and completed sandbox payment are recorded.']}[phase];status.className='checkout-status '+phase;status.innerHTML=`<span class="checkout-status-icon">${processing?'<span class="spinner"></span>':icon(phase==='paid'?'check':phase==='pending'?'clock':phase==='failed'?'close':'shield',24)}</span><div><span class="checkout-eyebrow">${phase==='paid'?'PAYMENT COMPLETE':'PAYMENT STATUS'}</span><h2>${copy[0]}</h2><p>${copy[1]}</p>${phase==='paid'?`<div class="receipt-meta"><strong>${money(p.cents)} USD</strong><span>PayPal capture: <code>${esc(p.capture)}</code></span>${p.paidAt?`<span>${fullDate(p.paidAt)}</span>`:''}</div>`:''}${notice&&phase!=='paid'?`<p class="payment-notice">${esc(notice)}</p>`:''}</div>`;}
  section.hidden=phase==='paid';accept.checked=p.accepted||accept.checked;accept.disabled=processing;payment.hidden=processing||phase==='pending'||phase==='unavailable';retry.hidden=!lastOrderId||processing||!notice||phase==='paid'||phase==='pending';errors.textContent='';
 };
 const closeButtons=()=>{try{Promise.resolve(buttons?.close?.()).catch(()=>{});}catch{}};
 const apply=next=>{const wasPaid=p.status==='paid';p=next;draw();if(p.status==='paid'&&p.capture){watcher?.stop();closeButtons();if(!wasPaid)announceWorkspaceChange();}};
 const check=async({force=false}={})=>{if(disposed||checkRunning||processing)return;checkRunning=true;if(force){checkButton.disabled=true;checkButton.textContent='Checking…';}try{
   const local=await api('client/'+token);if(disposed)return;apply(local.proposal);
   if(p.status!=='paid'&&p.hasOrder&&(force||Date.now()-lastProviderCheck>=8000)){lastProviderCheck=Date.now();const result=await api('client/'+token+'/refresh',{force});if(disposed)return;if(!confirmationFailed||result.paid||result.proposal.captureStatus==='PENDING'){notice='';confirmationFailed=false;}apply(result.proposal);}
  }catch(error){if(!disposed){notice='We could not verify the latest status. We will retry automatically. '+error.message;draw();}}finally{checkRunning=false;if(!disposed){checkButton.disabled=false;checkButton.textContent='Check now';}}};
 const confirm=async orderID=>{if(processing||disposed)return;lastOrderId=orderID;notice='';confirmationFailed=false;processing=true;draw();try{await api('client/'+token+'/capture',{orderID});if(!disposed){const fresh=await api('client/'+token);apply(fresh.proposal);}}catch(error){confirmationFailed=true;notice='Completion has not been confirmed. '+error.message;}finally{processing=false;if(!disposed){draw();await check({force:true});watcher?.wake();}}};
 retry.onclick=()=>confirm(lastOrderId);checkButton.onclick=()=>check({force:true});
 const acceptProposal=async()=>{if(!accept.checked)throw Error('Accept the additional work before continuing.');await api('client/'+token+'/accept',{accepted:true});p.accepted=true;};
 const focus=()=>watcher?.wake();window.addEventListener('focus',focus);document.addEventListener('visibilitychange',focus);
 watcher=createSerialPoller(()=>check(),{interval:4000});
 clientCleanup=()=>{disposed=true;watcher.stop();window.removeEventListener('focus',focus);document.removeEventListener('visibilitychange',focus);closeButtons();};draw();
 if(p.status==='paid')return;
 if(p.demo){document.querySelector('.payment-auto').hidden=true;payment.innerHTML='<button class="btn primary" id="sample-accept">Preview acceptance</button>';document.querySelector('#sample-accept').onclick=async()=>{try{await acceptProposal();toast('Sample accepted. Payments are disabled.')}catch(error){toast(error.message)}};return;}
 watcher.start();
 if(!config.paypal){payment.innerHTML='<div class="review-banner">PayPal sandbox is not configured. Ask the freelancer to connect it.</div>';return;}
 payment.innerHTML='<p class="hint"><span class="spinner"></span> Loading secure sandbox checkout…</p>';
 const mount=()=>{if(disposed||p.status==='paid')return;payment.innerHTML='';buttons=window.paypal.Buttons({style:{layout:'vertical',shape:'rect',label:'pay'},onClick:async(_,actions)=>{try{await acceptProposal();notice='';draw();return actions.resolve();}catch(error){notice=error.message;draw();return actions.reject();}},createOrder:async()=>{const order=await api('client/'+token+'/order',{});if(order.paid){await check({force:true});throw Error('This proposal is already paid.');}p.hasOrder=true;p.lastCheckout='started';lastOrderId=order.id;draw();watcher.wake();return order.id;},onApprove:data=>confirm(data.orderID),onCancel:async()=>{try{await api('client/'+token+'/cancel',{});p.lastCheckout='cancelled';}catch{}notice='';draw();watcher.wake();},onError:()=>{notice='Checkout did not finish. We are checking the latest status automatically before you retry.';draw();watcher.wake();}});buttons.render('#payment').catch(()=>{notice='PayPal checkout could not be displayed. Check your connection and reload this proposal.';draw();});};
 if(window.paypal?.Buttons)mount();else{let sdk=document.querySelector('script[data-paypal-sdk]');if(!sdk){sdk=document.createElement('script');sdk.dataset.paypalSdk='true';sdk.src='https://www.paypal.com/sdk/js?client-id='+encodeURIComponent(config.clientId)+'&currency=USD&intent=capture&components=buttons';document.head.appendChild(sdk);}sdk.addEventListener('load',mount,{once:true});sdk.addEventListener('error',()=>{if(!disposed){notice='PayPal could not load. Check your connection and reload this proposal.';draw();}},{once:true});}
}

function authScreen(mode='login'){
 landingCleanup();window.history.replaceState(null,'',mode==='signup'?'#create-account':'#sign-in');
 const signup=mode==='signup';document.title=(signup?'Create your account':'Sign in')+' · ScopePay';
 app.innerHTML=`<main class="auth-layout"><section class="auth-story"><a class="brand" href="/" aria-label="ScopePay home"><span class="mark">s<span></span></span>ScopePay<span class="brand-period">.</span></a><div class="auth-story-content"><div class="eyebrow">CLEAR SCOPE. FAIR PAY.</div><h1>Keep the relationship. <br><span>Get paid for the extra.</span></h1><p>Give every client request a clear path from agreement to approval—and payment.</p><div class="auth-flow"><div>${icon('review',20)}<span>Client request</span><small>“One more thing…”</small></div><span class="flow-connector"></span><div>${icon('spark',20)}<span>Scope clarity</span><small>Evidence & effort</small></div><span class="flow-connector"></span><div>${icon('check',20)}<span>Fair payment</span><small>Agreed & recorded</small></div></div><div class="auth-benefits"><span>${icon('check',14)} Evidence behind every decision</span><span>${icon('check',14)} Your rates, transparent calculations</span><span>${icon('check',14)} PayPal sandbox checkout</span></div></div><div class="auth-story-footer"><span>${icon('shield',16)} Your work stays in your account</span><span>Independent hackathon prototype</span></div></section><section class="auth-main"><div class="auth-toolbar"><a class="auth-home" href="#home">${icon('arrow',14)} Back to ScopePay</a>${themeButton()}</div><div class="auth-card"><span class="auth-kicker">${icon(signup?'user':'lock',17)}${signup?'CREATE YOUR ACCOUNT':'WELCOME BACK'}</span><h2>${signup?'A workspace of your own.':'Good to see you again.'}</h2><p class="muted">${signup?'Bring your agreements, reviews, and payments together.':'Sign in to pick up where your work left off.'}</p>${signup&&authInfo.firstAccount&&authInfo.legacyProjects?`<div class="notice migration-note">${icon('database',19)}<p><strong>Your existing work is ready.</strong>Your ${authInfo.legacyProjects} saved projects and their history will be linked to this first account.</p></div>`:''}<form id="auth-form">${signup?'<div class="field"><label for="auth-name">Full name</label><input id="auth-name" name="name" autocomplete="name" required maxlength="80" placeholder="Your name"></div>':''}<div class="field"><label for="auth-email">Email address</label><input id="auth-email" type="email" name="email" autocomplete="username" required maxlength="254" placeholder="you@example.com"></div><div class="field"><label for="auth-password">Password</label><div class="password-input"><input id="auth-password" type="password" name="password" autocomplete="${signup?'new-password':'current-password'}" required minlength="${signup?'12':'1'}" maxlength="128" placeholder="${signup?'At least 12 characters':'Enter your password'}"><button type="button" class="icon-btn" id="toggle-password" aria-label="Show password">${icon('eye',18)}</button></div>${signup?'<p class="hint">Use a unique password with at least 12 characters.</p>':''}</div>${signup?'<div class="field"><label for="auth-rate">Default hourly rate <span class="label-optional">Optional</span></label><div class="currency-input"><span>$</span><input id="auth-rate" name="hourlyRate" inputmode="decimal" placeholder="20.00"><span>USD / hour</span></div><p class="hint">You can set or change this in your account later.</p></div>':''}${signup&&authInfo.ownerSetupRequired?'<div class="field"><label for="owner-setup">Owner setup code</label><input id="owner-setup" name="setupToken" type="password" autocomplete="off" required minlength="32" maxlength="256"><p class="hint">Use OWNER_SETUP_TOKEN from your Render service environment. This is needed only for the first account.</p></div>':''}<div class="form-error" role="alert"></div><button class="btn primary auth-submit" type="submit">${signup?'Create my workspace':'Sign in to workspace'}${icon('arrow',17)}</button></form><p class="auth-switch">${signup?'Already have an account?':'New to ScopePay?'} <button class="text-button" id="auth-switch">${signup?'Sign in':'Create an account'}</button></p><div class="auth-footnote">${icon('lock',13)}<p>Password account · Email verification and email-based password recovery are not enabled yet.</p></div></div><footer class="auth-footer"><span>© ${new Date().getFullYear()} ScopePay</span><span>Sandbox workspace · No real money</span></footer></section></main>`;
 document.querySelector('#auth-switch').onclick=()=>authScreen(signup?'login':'signup');document.querySelector('#toggle-password').onclick=e=>{const input=document.querySelector('#auth-password');input.type=input.type==='password'?'text':'password';e.currentTarget.setAttribute('aria-label',input.type==='password'?'Show password':'Hide password');};
 document.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();await submit(e.target,async()=>{await api('auth/'+(signup?'signup':'login'),Object.fromEntries(new FormData(e.target)));view='overview';await refresh();window.history.replaceState(null,'','#workspace');render();toast(signup?'Your workspace is ready.':'Welcome back. Your work is up to date.');})};window.scrollTo(0,0);
}
function savedReviews(){
 shell(heading('SCOPE INTELLIGENCE','The reasoning stays with the work.','Revisit saved findings, evidence, and effort estimates without another AI request.')+`<section class="panel"><div class="list-toolbar"><div class="input-icon">${icon('search',17)}<input id="review-search" aria-label="Search saved reviews" placeholder="Search client requests…" value="${esc(listingQuery)}"></div><select id="review-project" aria-label="Filter reviews by project"><option value="all">All projects</option>${state.projects.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div><div id="review-results"></div></section>`);
 const draw=()=>{const rows=state.reviews.filter(r=>(listingFilter==='all'||r.projectId===listingFilter)&&(!listingQuery||r.request.toLowerCase().includes(listingQuery))).slice().reverse();document.querySelector('#review-results').innerHTML=rows.length?rows.map(r=>{const p=state.projects.find(p=>p.id===r.projectId);return `<article class="review-row"><span class="review-row-icon">${icon('spark',20)}</span><div><div class="review-row-heading"><h2>${esc(p?.name||'Scope review')}</h2>${r.demo?badge('','Sample'):''}<time>${relative(r.created)}</time></div><p class="request-excerpt">${esc(r.request)}</p><div class="finding-counts"><span class="included">${r.findings.filter(f=>f.status==='included').length} included</span><span class="extra">${r.findings.filter(f=>f.status==='extra').length} extra</span><span class="clarify">${r.findings.filter(f=>f.status==='clarify').length} to clarify</span></div></div><button class="btn" data-open-review="${r.id}">View findings ${icon('arrow',15)}</button></article>`}).join(''):emptyState('review','No reviews found','Review a client request from a project, or adjust your search.');bindActions(document.querySelector('#review-results'));};document.querySelector('#review-project').value=listingFilter;document.querySelector('#review-search').oninput=e=>{listingQuery=e.target.value.toLowerCase();draw()};document.querySelector('#review-project').onchange=e=>{listingFilter=e.target.value;draw()};draw();
}
async function profilePage(){
 const requestedView=view;const account=await api('account');if(view!==requestedView)return;const u=account.user;
 shell(heading('ACCOUNT SETTINGS','Your workspace, your way.','Manage your identity, pricing defaults, and account security.')+`<div class="account-hero"><div class="account-avatar">${esc(initials(u.name))}<span>${icon('user',13)}</span></div><div><h2>${esc(u.name)}</h2><p>${esc(u.email)}</p><span>Member since ${fullDate(u.created)}</span></div>${badge('',u.role==='owner'?'Installation owner':'Member')}</div><div class="account-tabs" role="tablist" aria-label="Account settings">${[['profile','user','Profile & pricing'],['security','shield','Security'],['data','database','Data & activity']].map(([id,symbol,label])=>`<button role="tab" id="tab-${id}" aria-controls="account-${id}" aria-selected="${accountTab===id}" tabindex="${accountTab===id?'0':'-1'}" data-account-tab="${id}" class="${accountTab===id?'active':''}">${icon(symbol,17)}${label}</button>`).join('')}</div>
 <section id="account-profile" role="tabpanel" aria-labelledby="tab-profile" ${accountTab==='profile'?'':'hidden'}><div class="settings-grid"><section class="panel"><div class="panel-head"><div><h2>Personal information</h2><p>The details associated with your workspace</p></div></div><form id="profile-form"><div class="panel-body"><div class="two"><div class="field"><label for="profile-name">Full name</label><input id="profile-name" name="name" required maxlength="80" autocomplete="name" value="${esc(u.name)}"></div><div class="field"><label for="profile-email">Email address</label><input id="profile-email" type="email" value="${esc(u.email)}" readonly><p class="hint">Your sign-in ID. Email changes are not enabled yet.</p></div></div><div class="section-divider"></div><h3 class="form-section-title">Your pricing default</h3><p class="form-section-copy">AI estimates the effort. Your hourly rate determines the quote.</p><div class="field rate-field"><label for="profile-rate">Default hourly rate</label><div class="currency-input"><span>$</span><input id="profile-rate" name="hourlyRate" inputmode="decimal" value="${u.hourlyRate?(u.hourlyRate/100).toFixed(2):''}" placeholder="20.00"><span>USD / hour</span></div></div><div class="notice">${icon('help',17)}<p>Used for new projects. Existing project overrides, saved estimates, and sent proposals keep their original values.</p></div><div class="form-error" role="alert"></div></div><div class="panel-form-footer"><p id="profile-save-state">Changes apply after you save.</p><button class="btn primary" type="submit">Save changes ${icon('check',16)}</button></div></form></section><aside class="panel account-aside"><span class="feature-icon violet">${icon('spark',22)}</span><h3>A rate with a reason.</h3><p>Your quotes show task hours, your saved rate, and the assumptions behind the calculation. You approve the result before a client sees it.</p><div class="rate-example"><span>Your current default</span><strong>${u.hourlyRate?money(u.hourlyRate):'Not set'}<small>${u.hourlyRate?'/ hour':''}</small></strong></div><div class="appearance-setting"><label for="theme-preference">Appearance</label><select id="theme-preference" data-theme-select>${themeOptions()}</select><p class="hint">Saved in this browser. Applies across ScopePay.</p></div></aside></div></section>
 <section id="account-security" role="tabpanel" aria-labelledby="tab-security" ${accountTab==='security'?'':'hidden'}><div class="settings-grid"><section class="panel"><div class="panel-head"><div><h2>Password & access</h2><p>Keep your account credentials private</p></div>${icon('shield',20)}</div><form id="password-form"><div class="panel-body"><div class="field"><label for="current-password">Current password</label><input id="current-password" type="password" name="currentPassword" autocomplete="current-password" required maxlength="128"></div><div class="field"><label for="new-password">New password</label><input id="new-password" type="password" name="newPassword" autocomplete="new-password" required minlength="12" maxlength="128"><p class="hint">At least 12 characters. Changing this signs out all other sessions.</p></div><div class="form-error" role="alert"></div></div><div class="panel-form-footer"><span class="small muted">Never share your password.</span><button class="btn primary" type="submit">Update password ${icon('lock',15)}</button></div></form></section><aside class="panel"><div class="panel-head"><h2>Account access</h2></div><div class="panel-body"><div class="security-row"><span class="soft-icon">${icon('lock',18)}</span><div><strong>${account.sessions.length} active session${account.sessions.length===1?'':'s'}</strong><p>Sessions expire after 7 days.</p></div></div><div class="security-row"><span class="soft-icon">${icon('mail',18)}</span><div><strong>Email verification</strong><p>Not enabled in this local version.</p></div></div><p class="hint">Signing out ends this browser session. Your saved work stays in your account.</p><button class="btn signout-button" data-logout>${icon('logout',16)}Sign out of this session</button></div></aside></div></section>
 <section id="account-data" role="tabpanel" aria-labelledby="tab-data" ${accountTab==='data'?'':'hidden'}><div class="settings-grid"><div><section class="panel"><div class="panel-head"><div><h2>Your saved workspace</h2><p>Account-owned records, organized by project</p></div></div><div class="account-counts">${[['Projects',state.projects.length],['Scope reviews',state.reviews.length],['Proposals',state.proposals.length],['Paid proposals',state.proposals.filter(p=>p.status==='paid').length]].map(([label,value])=>`<div><strong>${value}</strong><span>${label}</span></div>`).join('')}</div><div class="panel-body"><div class="export-box"><span class="feature-icon blue">${icon('download',21)}</span><div><h3>Take a copy of your work</h3><p>Download your profile, projects, reviews, and proposals as JSON.</p></div><button id="export-account" class="btn">Export workspace ${icon('download',15)}</button></div><p class="hint">Your export includes access-bearing client links. Keep the file private.</p></div></section><div class="notice" style="margin-top:20px">${icon('database',19)}<p>This installation stores work locally. Cloud synchronization and public hosting are not enabled.</p></div></div><aside class="panel"><div class="panel-head"><h2>Recent activity</h2></div><div class="account-activity">${account.activity.slice(0,10).map(a=>`<div class="activity-row"><span class="activity-symbol">${icon(a.event.startsWith('account')?'user':a.event.startsWith('profile')?'user':'review',15)}</span><span><strong>${esc(a.event.replaceAll('.',' '))}</strong><small>${fullDate(a.created)}</small></span></div>`).join('')||emptyState('clock','No recent activity','Your account activity will appear here.')}</div></aside></div></section>`);
 const tabs=[...document.querySelectorAll('[data-account-tab]')];const changeTab=id=>{accountTab=id;for(const b of tabs){const selected=b.dataset.accountTab===id;b.classList.toggle('active',selected);b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;document.querySelector('#account-'+b.dataset.accountTab).hidden=!selected}};
 tabs.forEach((b,i)=>{b.onclick=()=>changeTab(b.dataset.accountTab);b.onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();const next=tabs[(i+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length];changeTab(next.dataset.accountTab);next.focus()}}});
 document.querySelector('#profile-form').onsubmit=async e=>{e.preventDefault();await submit(e.target,async()=>{await api('profile',Object.fromEntries(new FormData(e.target)));await refresh();if(view==='profile')await profilePage();toast('Profile updated. Existing quotes are unchanged.');})};document.querySelector('#password-form').onsubmit=async e=>{e.preventDefault();await submit(e.target,async()=>{await api('profile/password',Object.fromEntries(new FormData(e.target)));e.target.reset();toast('Password updated. Other sessions were signed out.');})};document.querySelector('#export-account').onclick=async()=>{try{const data=await api('account/export');downloadFile('scopepay-workspace.json',JSON.stringify(data,null,2),'application/json');toast('Your workspace export is ready.');}catch(e){toast(e.message)}};
}
function badge(s,label){return `<span class="badge ${esc(s)}"><span class="badge-dot"></span>${esc(label||({included:'Included',extra:'Extra work',clarify:'Needs clarification',paid:'Paid',accepted:'Accepted · unpaid',awaiting:'Awaiting approval'}[s]||'Awaiting payment'))}</span>`;}

function billingChart(){
 const now=new Date();const months=Array.from({length:6},(_,i)=>{const d=new Date(now.getFullYear(),now.getMonth()-5+i,1);return {key:d.getFullYear()+'-'+d.getMonth(),label:d.toLocaleDateString('en-US',{month:'short'}),paid:0,quoted:0}});
 for(const p of realProposals()){const created=new Date(p.created),quoted=months.find(m=>m.key===created.getFullYear()+'-'+created.getMonth());if(quoted)quoted.quoted+=p.cents;if(p.status==='paid'){const d=new Date(p.paidAt||p.created),m=months.find(m=>m.key===d.getFullYear()+'-'+d.getMonth());if(m)m.paid+=p.cents;}}
 const max=Math.max(10000,...months.flatMap(m=>[m.paid,m.quoted]));
 return `<div class="chart-area"><div class="chart-y"><span>${money(max)}</span><span>${money(max/2)}</span><span>$0</span></div><div class="chart-plot"><div class="chart-gridlines"><i></i><i></i><i></i></div>${months.map(m=>`<div class="chart-column"><div class="chart-bars"><div class="chart-bar quoted" style="height:${m.quoted/max*100}%" title="${m.label}: ${money(m.quoted)} quoted"><span class="sr-only">${m.label}: ${money(m.quoted)} quoted</span></div><div class="chart-bar paid" style="height:${m.paid/max*100}%" title="${m.label}: ${money(m.paid)} paid"><span class="sr-only">${m.label}: ${money(m.paid)} paid</span></div></div><span>${m.label}</span></div>`).join('')}</div></div><p class="chart-caption">${realProposals().length?'Amounts from saved proposals and completed sandbox captures.':'Your proposal and payment history will appear here as you start working.'}</p>`;
}

function projectRow(p){const count=state.proposals.filter(q=>q.projectId===p.id).length;return `<div class="project"><span class="project-icon">${esc(initials(p.name))}</span><div class="project-info"><h3>${esc(p.name)} ${p.demo?badge('','Sample'):''}</h3><p>${esc(p.client)} <span>·</span> ${count} proposal${count===1?'':'s'}</p></div><button class="row-arrow" data-open-project="${p.id}" aria-label="Open ${esc(p.name)}">${icon('arrow',17)}</button></div>`;}

function projectsPage(){
 shell(heading('PROJECTS','Great work starts with clear scope.','Keep your agreements, requests, and additions connected.',btn(icon('plus',16)+'New project','create',true))+`<section class="panel listing-panel"><div class="list-toolbar"><div class="input-icon">${icon('search',17)}<input id="project-search" aria-label="Search projects" placeholder="Search projects or clients…" value="${esc(listingQuery)}"></div><div class="toolbar-right"><select id="project-type" aria-label="Filter project type"><option value="all">All projects</option><option value="real">My projects</option><option value="sample">Samples</option></select><select id="project-sort" aria-label="Sort projects"><option value="recent">Newest first</option><option value="name">Name A–Z</option></select></div></div><div id="project-results"></div></section>`);
 const draw=()=>{const rows=state.projects.filter(p=>(listingFilter==='all'||(listingFilter==='sample')===!!p.demo)&&(!listingQuery||(p.name+' '+p.client).toLowerCase().includes(listingQuery))).sort((a,b)=>listingSort==='name'?a.name.localeCompare(b.name):new Date(b.created)-new Date(a.created));document.querySelector('#project-results').innerHTML=rows.length?`<div class="project-cards">${rows.map(p=>`<article class="project-card"><div class="project-card-top"><span class="project-icon">${esc(initials(p.name))}</span>${p.demo?badge('','Sample'):badge('included','Active')}</div><h2>${esc(p.name)}</h2><p class="project-client">${esc(p.client)}</p><p class="scope-preview">${esc(p.scope)}</p><div class="project-card-meta"><span>${icon('review',14)}${state.reviews.filter(r=>r.projectId===p.id).length} review${state.reviews.filter(r=>r.projectId===p.id).length===1?'':'s'}</span><span>${icon('receipt',14)}${state.proposals.filter(q=>q.projectId===p.id).length} proposal${state.proposals.filter(q=>q.projectId===p.id).length===1?'':'s'}</span></div><div class="project-card-bottom"><span>${p.hourlyRate?money(p.hourlyRate)+'/hr':'Rate not set'}</span><button class="text-button" data-open-project="${p.id}">View project ${icon('arrow',14)}</button></div></article>`).join('')}</div>`:emptyState('folder',state.projects.length?'No matching projects':'A place for your first agreement',state.projects.length?'Try another name or reset your filters.':'Create a project and save its original scope.',state.projects.length?'<button class="btn" id="reset-projects">Clear filters</button>':btn('New project','create',true));bindActions(document.querySelector('#project-results'));const reset=document.querySelector('#reset-projects');if(reset)reset.onclick=()=>{listingQuery='';listingFilter='all';projectsPage()};};
 document.querySelector('#project-type').value=listingFilter;document.querySelector('#project-sort').value=listingSort;document.querySelector('#project-search').oninput=e=>{listingQuery=e.target.value.toLowerCase();draw()};document.querySelector('#project-type').onchange=e=>{listingFilter=e.target.value;draw()};document.querySelector('#project-sort').onchange=e=>{listingSort=e.target.value;draw()};draw();
}

function projectPage(){const p=current,reviews=state.reviews.filter(r=>r.projectId===p.id),proposals=state.proposals.filter(q=>q.projectId===p.id);shell(`<button class="back" data-nav="projects">${icon('arrow',14)} All projects</button>`+heading('PROJECT WORKSPACE',esc(p.name),`Client: ${esc(p.client)} · Created ${fullDate(p.created)}`,`<button class="btn primary" data-project="${p.id}">${icon('spark',16)} Review a request</button>`)+`<div class="project-summary"><div><span>Hourly rate</span><strong>${p.hourlyRate?money(p.hourlyRate)+'/hr':'Not set'}</strong></div><div><span>Saved reviews</span><strong>${reviews.length}</strong></div><div><span>Proposals</span><strong>${proposals.length}</strong></div><div><span>${p.demo?'Sample value':'Extra work paid'}</span><strong>${money(proposals.filter(q=>q.status==='paid').reduce((sum,q)=>sum+q.cents,0))}</strong></div></div><div class="grid"><section class="panel"><div class="panel-head"><div><h2>Original agreement</h2><p>The source of truth for scope reviews</p></div>${badge('','Source')}</div><div class="panel-body"><p class="source agreement-text">${esc(p.scope)}</p></div></section><aside class="panel"><div class="panel-head"><h2>Project history</h2></div><div class="panel-body">${reviews.length?reviews.slice().reverse().map(r=>`<button class="mini-history" data-open-review="${r.id}"><span class="soft-icon">${icon('review',17)}</span><span><strong>Scope review</strong><small>${r.findings.length} finding${r.findings.length===1?'':'s'} · ${relative(r.created)}</small></span>${icon('chevron',14)}</button>`).join(''):emptyState('review','No requests reviewed','Review a client request to start this project’s history.')}${proposals.map(q=>`<button class="mini-history" data-open-proposal="${q.id}"><span class="soft-icon">${icon('receipt',17)}</span><span><strong>${money(q.cents)} proposal</strong><small>${statusLabel(q)}</small></span>${icon('chevron',14)}</button>`).join('')}</div></aside></div>`);}

function filteredProposals(){return state.proposals.filter(p=>(listingFilter==='all'||listingFilter==='sample'&&p.demo||listingFilter===statusKey(p)&&!p.demo)&&(!listingQuery||(p.projectName+' '+p.client+' '+(p.capture||'')).toLowerCase().includes(listingQuery))).sort((a,b)=>new Date(b.created)-new Date(a.created));}

function bindActions(root=app){
 root.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>navigate(el.dataset.nav));
 root.querySelectorAll('[data-help]').forEach(el=>el.onclick=helpDialog);
 root.querySelectorAll('[data-logout]').forEach(el=>el.onclick=signOut);
 root.querySelectorAll('[data-project]').forEach(el=>el.onclick=()=>{current=state.projects.find(p=>p.id===el.dataset.project);view='request';requestPage()});
 root.querySelectorAll('[data-open-project]').forEach(el=>el.onclick=()=>openProject(el.dataset.openProject));
 root.querySelectorAll('[data-open-review],[data-review]').forEach(el=>el.onclick=()=>openSavedReview(el.dataset.openReview||el.dataset.review));
 root.querySelectorAll('[data-open-proposal],[data-proposal]').forEach(el=>el.onclick=()=>openProposal(el.dataset.openProposal||el.dataset.proposal));
 root.querySelectorAll('[data-action]').forEach(el=>el.onclick=async()=>{try{if(el.dataset.action==='sample'){el.disabled=true;const r=await api('sample',{});current=r.project;review=r.review;await refresh();view='review';reviewPage();}else if(el.dataset.action==='refresh'){el.disabled=true;el.innerHTML='<span class="spinner"></span>Checking…';const result=await api('reconcile',{});await refresh();if(view==='history')history();toast(result.results.some(r=>r.error)?'Some payments could not be checked. Review your connections.':'Payment status refreshed. No new charge was initiated.');}else navigate(el.dataset.action);}catch(e){el.disabled=false;toast(e.message)}});
}

async function signOut(){try{await api('auth/logout',{});state={projects:[],reviews:[],proposals:[],config:{},user:null};current=null;review=null;view='overview';authInfo=await api('auth');authScreen('login');toast('You’ve been signed out. Your work is saved.');}catch(e){toast(e.message)}}

