function icon(name,size=18){return `<svg class="icon" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;}
const initials=s=>String(s||'').trim().split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase();
const fullDate=s=>s?new Date(s).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'—';
const relative=s=>{if(!s)return 'Saved';const days=Math.floor((Date.now()-new Date(s))/86400000);return days<=0?'Today':days===1?'Yesterday':days<7?`${days} days ago`:fullDate(s)};
const realProposals=()=>state.proposals.filter(p=>!p.demo);
const statusKey=p=>p.status==='paid'?'paid':p.accepted?'accepted':'awaiting';
const statusLabel=p=>({paid:'Paid',accepted:'Accepted · unpaid',awaiting:'Awaiting approval'}[statusKey(p)]);
const emptyState=(symbol,title,description,action='')=>`<div class="empty"><span class="empty-icon">${icon(symbol,25)}</span><h3>${title}</h3><p>${description}</p>${action}</div>`;
const navItems=[['overview','grid','Overview'],['projects','folder','Projects'],['reviews','review','Scope reviews'],['history','receipt','Proposals'],['settings','plug','Connections'],['profile','user','Account']];
let listingQuery='',listingFilter='all',listingSort='recent',accountTab='profile';
function navigate(next){view=next;listingQuery='';listingFilter='all';listingSort='recent';render();}
function openProject(id){current=state.projects.find(p=>p.id===id);if(current){view='project';projectPage();}}
function openSavedReview(id){review=state.reviews.find(r=>r.id===id);if(review){current=state.projects.find(p=>p.id===review.projectId);view='review';reviewPage();}}
function openProposal(id){const p=state.proposals.find(p=>p.id===id);if(p){view='proposal';proposalReady(p);}}
function showDialog(title,body,kind=''){
 let d=document.querySelector('#workspace-dialog');if(d)d.remove();
 d=document.createElement('dialog');d.id='workspace-dialog';d.className='workspace-dialog '+kind;d.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-btn" aria-label="Close dialog">${icon('close')}</button></div>${body}`;app.append(d);d.querySelector('.icon-btn').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d)d.close()});d.addEventListener('close',()=>d.remove());d.showModal();return d;
}
function helpDialog(){showDialog('Your ScopePay workspace',`<div class="dialog-body"><div class="help-intro">${icon('shield',26)}<p>From a client’s request to an agreed, paid addition—every decision stays connected to the original scope.</p></div><div class="help-grid"><article><strong>1. Define your project</strong><p>Save the agreed deliverables and your hourly rate.</p></article><article><strong>2. Review a request</strong><p>Check AI findings, evidence, estimated tasks, and assumptions.</p></article><article><strong>3. Agree on the extra</strong><p>Share a proposal after you approve its calculated total.</p></article><article><strong>4. Record payment</strong><p>Clients use PayPal sandbox. Paid status requires a verified capture.</p></article></div><div class="notice">${icon('lock')}<p>This version runs locally. Client links work on this computer. Rates and estimates are reviewable; no real money moves in sandbox checkout.</p></div><p class="hint">ScopePay is an independent hackathon prototype using PayPal sandbox. It is not an official PayPal product.</p></div>`);}
function searchDialog(){
 const d=showDialog('Search your workspace',`<div class="command-input">${icon('search')}<input id="command-query" aria-label="Search workspace" placeholder="Projects, clients, requests, proposals…" autocomplete="off"><kbd>esc</kbd></div><div id="command-results" class="command-results"></div><div class="command-footer">Search saved records · No AI request required</div>`,'command-dialog');
 const input=d.querySelector('input'),results=d.querySelector('#command-results');
 const update=()=>{const q=input.value.toLowerCase().trim();const entries=[...state.projects.map(p=>({type:'Project',icon:'folder',title:p.name,detail:p.client,id:p.id,action:'project'})),...state.reviews.map(r=>({type:'Review',icon:'review',title:state.projects.find(p=>p.id===r.projectId)?.name||'Scope review',detail:r.request,id:r.id,action:'review'})),...state.proposals.map(p=>({type:'Proposal',icon:'receipt',title:p.projectName,detail:p.client+' · '+money(p.cents)+' · '+statusLabel(p),id:p.id,action:'proposal'}))].filter(e=>!q||(e.title+' '+e.detail).toLowerCase().includes(q)).slice(0,12);
 results.innerHTML=entries.length?entries.map(e=>`<button class="command-result" data-kind="${e.action}" data-id="${esc(e.id)}"><span class="soft-icon">${icon(e.icon)}</span><span><strong>${esc(e.title)}</strong><small>${esc(e.detail.slice(0,90))}</small></span><span class="command-type">${e.type}</span>${icon('arrow',15)}</button>`).join(''):emptyState('search','No matching work','Try a project name, client, or a shorter phrase.');
 results.querySelectorAll('button[data-id]').forEach(b=>b.onclick=()=>{d.close();({project:openProject,review:openSavedReview,proposal:openProposal}[b.dataset.kind])(b.dataset.id)});
 };input.oninput=update;update();input.focus();
}
function attentionDialog(){const pending=realProposals().filter(p=>p.status!=='paid');const d=showDialog('Needs attention',`<div class="dialog-body">${pending.length?`<p class="muted small">${pending.length} proposal${pending.length===1?'':'s'} awaiting approval or payment.</p>${pending.map(p=>`<button class="attention-row" data-id="${p.id}"><span class="soft-icon amber">${icon('clock')}</span><span><strong>${esc(p.projectName)}</strong><small>${esc(p.client)} · ${statusLabel(p)}</small></span><strong>${money(p.cents)}</strong>${icon('chevron',15)}</button>`).join('')}`:emptyState('check','You’re all caught up','There are no unpaid proposals in this workspace.')}</div>`);d.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>{d.close();openProposal(b.dataset.id)});}
function copyText(text){navigator.clipboard.writeText(text).then(()=>toast('Link copied to clipboard.')).catch(()=>toast('Could not copy automatically. Select and copy the link.'));}
function downloadFile(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportProposals(){const csv=v=>'"'+String(v??'').replace(/^[\s]*[=+\-@]/,"'$&").replaceAll('"','""')+'"';const rows=[['Project','Client','Amount USD','Status','Created','Capture ID'],...filteredProposals().map(p=>[p.projectName,p.client,(p.cents/100).toFixed(2),statusLabel(p),fullDate(p.created),p.capture||''])];downloadFile('scopepay-proposals.csv',rows.map(row=>row.map(csv).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Proposal report exported.');}
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&state.user&&location.pathname!=='/client'){e.preventDefault();searchDialog();}});

function themeButton(extra=''){const dark=document.documentElement.dataset.theme==='dark';return `<button class="theme-toggle ${extra}" type="button" data-theme-toggle aria-label="Switch to ${dark?'light':'dark'} theme" aria-pressed="${dark}" title="Switch to ${dark?'light':'dark'} theme">${icon(dark?'sun':'moon',17)}<span>${dark?'Light':'Dark'}</span></button>`;}
function readThemeChoice(){try{const t=localStorage.getItem('scopepay-theme');return ['light','dark'].includes(t)?t:null;}catch{return null;}}
function themeOptions(){const choice=readThemeChoice()||'system';return [['system','Use device setting'],['light','Light'],['dark','Dark']].map(([v,t])=>`<option value="${v}" ${choice===v?'selected':''}>${t}</option>`).join('');}
function applyTheme(theme,save=false){document.documentElement.dataset.theme=theme;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',theme==='dark'?'#101d18':'#f7f6ef');if(save){try{localStorage.setItem('scopepay-theme',theme);}catch{}}document.querySelectorAll('[data-theme-toggle]').forEach(b=>{const next=theme==='dark'?'light':'dark';b.setAttribute('aria-label','Switch to '+next+' theme');b.setAttribute('aria-pressed',String(theme==='dark'));b.title='Switch to '+next+' theme';b.innerHTML=icon(next==='dark'?'moon':'sun',17)+`<span>${next==='dark'?'Dark':'Light'}</span>`;});document.querySelectorAll('[data-theme-select]').forEach(el=>el.value=readThemeChoice()||'system');}
document.addEventListener('click',e=>{if(e.target.closest('[data-theme-toggle]'))applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark',true);});
document.addEventListener('change',e=>{if(e.target.matches('[data-theme-select]')){if(e.target.value==='system'){try{localStorage.removeItem('scopepay-theme');}catch{}applyTheme(systemTheme.matches?'dark':'light');}else applyTheme(e.target.value,true);}});
const systemTheme=matchMedia('(prefers-color-scheme: dark)');systemTheme.addEventListener('change',e=>{if(!readThemeChoice())applyTheme(e.matches?'dark':'light');});window.addEventListener('storage',e=>{if(e.key==='scopepay-theme')applyTheme(readThemeChoice()||(systemTheme.matches?'dark':'light'));});

applyTheme(document.documentElement.dataset.theme||(systemTheme.matches?'dark':'light'));
function startOrbitScene(art,scene,initialPaused){
 const cards=[...scene.querySelectorAll('.art-note')],phases=[-140,-20,100],lift=cards.map(()=>0);
 let frame=0,angle=0,last=0,speed=1,paused=initialPaused,visible=true,hovered=false,focused=null,pointed=null,inspectionBounds=null,disposed=false,width=art.clientWidth,height=art.clientHeight;
 const active=()=>pointed||focused;
 const identify=node=>node instanceof Element?node.closest('.art-note'):null;
 const highlight=()=>cards.forEach(card=>card.classList.toggle('is-inspected',card===active()));
 cards.forEach((card,i)=>{card.tabIndex=0;card.setAttribute('role','group');card.setAttribute('aria-label',['Client request preview','Scope analysis preview','Proposal preview'][i]);});
 const draw=()=>{cards.forEach((card,i)=>{const a=(angle+phases[i])*Math.PI/180,depth=Math.sin(a),pop=lift[i],x=Math.cos(a)*width*(width<300?.20:.265)*(1-pop*.80),y=depth*height*.29*(1-pop*.20)-pop*6,z=depth*62*(1-pop)+pop*150;card.style.setProperty('--ox',x.toFixed(2)+'px');card.style.setProperty('--oy',y.toFixed(2)+'px');card.style.setProperty('--oz',z.toFixed(2)+'px');card.style.setProperty('--rz',(Math.cos(a)*-4*(1-pop*.7)).toFixed(2)+'deg');card.style.setProperty('--depth',((depth+1)/2).toFixed(3));card.style.setProperty('--oscale',(1+pop*.08).toFixed(4));});scene.style.setProperty('--orbit-angle',angle.toFixed(2)+'deg');};
 const canRun=()=>!disposed&&!paused&&visible&&!document.hidden;
 const tick=time=>{if(!canRun()){frame=0;last=0;return;}const dt=last?Math.min(time-last,64):16;last=time;
  speed+=((hovered||focused? .55:1)-speed)*(1-Math.exp(-dt/280));
  angle=(angle+dt*.0075*speed)%360;
  cards.forEach((card,i)=>{lift[i]+=((card===active()?1:0)-lift[i])*(1-Math.exp(-dt/110));});
  draw();frame=requestAnimationFrame(tick);
 };
 const sync=()=>{if(canRun()){if(!frame){last=0;frame=requestAnimationFrame(tick);}}else{cancelAnimationFrame(frame);frame=0;last=0;}art.classList.toggle('orbit-resting',paused||!visible||document.hidden);};
 const resize=new ResizeObserver(()=>{width=art.clientWidth;height=art.clientHeight;draw();});resize.observe(art);
 const observer=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;sync();},{threshold:.05});observer.observe(art);
 const enter=()=>{hovered=matchMedia('(hover:hover) and (pointer:fine)').matches;};
 const leave=()=>{hovered=false;pointed=null;inspectionBounds=null;highlight();};
 const move=e=>{if(!matchMedia('(hover:hover) and (pointer:fine)').matches)return;
  const candidate=identify(e.target);
  if(candidate){if(candidate!==pointed)inspectionBounds=candidate.getBoundingClientRect();pointed=candidate;}
  else if(pointed){const currentBounds=pointed.getBoundingClientRect(),inside=r=>r&&e.clientX>=r.left-8&&e.clientX<=r.right+8&&e.clientY>=r.top-8&&e.clientY<=r.bottom+8;if(!inside(inspectionBounds)&&!inside(currentBounds)){pointed=null;inspectionBounds=null;}}
  highlight();
 };
 const focus=e=>{const card=identify(e.target);if(card?.matches(':focus-visible')){focused=card;highlight();}};
 const blur=()=>{focused=null;highlight();};
 art.addEventListener('pointerenter',enter);art.addEventListener('pointerleave',leave);art.addEventListener('pointermove',move);scene.addEventListener('focusin',focus);scene.addEventListener('focusout',blur);document.addEventListener('visibilitychange',sync);draw();sync();
 return {setPaused(value){paused=value;sync();},dispose(){disposed=true;cancelAnimationFrame(frame);resize.disconnect();observer.disconnect();art.removeEventListener('pointerenter',enter);art.removeEventListener('pointerleave',leave);art.removeEventListener('pointermove',move);scene.removeEventListener('focusin',focus);scene.removeEventListener('focusout',blur);document.removeEventListener('visibilitychange',sync);}};
}


